package domain

import (
	"context"
	"database/sql"
)

type fenceExec interface {
	ExecContext(ctx context.Context, query string, args ...any) (sql.Result, error)
	QueryRowContext(ctx context.Context, query string, args ...any) *sql.Row
}

// EnsureClientSessionFence extends the restore barrier to v2.4 client sessions when the
// client_sessions table is present (it is absent on pre-W03 schemas): writer_epoch can
// never regress, and advancing the epoch of a session whose (project, run) is under a
// restore barrier requires the same fresh reconciliation evidence as Run leases.
// Open sessions with a run are seeded into the barriers so restored snapshots cannot
// silently re-handoff writers. Returns nil (no-op) when client_sessions does not exist.
func EnsureClientSessionFence(ctx context.Context, ex fenceExec) error {
	return installClientSessionFence(ctx, ex, true)
}

// Ordinary startup installs the invariant triggers without marking active runs
// as restored. Only the restore path may advance the reconciliation barrier.
func installClientSessionFence(ctx context.Context, ex fenceExec, restored bool) error {
	var present int
	row := ex.QueryRowContext(ctx, `SELECT count(*) FROM sqlite_master WHERE type='table' AND name='client_sessions'`)
	if err := row.Scan(&present); err != nil {
		return err
	}
	if present == 0 {
		return nil
	}
	// CREATE TABLE IF NOT EXISTS cannot extend a database created by an older
	// client. The nullable reference indexes a sealed journal projection; it
	// neither replaces the message journal nor changes session or writer state.
	var transcriptColumn int
	if err := ex.QueryRowContext(ctx, `SELECT count(*) FROM pragma_table_info('client_sessions') WHERE name='transcript_artifact_id'`).Scan(&transcriptColumn); err != nil {
		return err
	}
	if transcriptColumn == 0 {
		if _, err := ex.ExecContext(ctx, `ALTER TABLE client_sessions ADD COLUMN transcript_artifact_id TEXT`); err != nil {
			return err
		}
	}
	if _, err := ex.ExecContext(ctx, `CREATE TABLE IF NOT EXISTS backup_restore_barriers(project TEXT NOT NULL,run TEXT NOT NULL,restored_at TEXT NOT NULL,PRIMARY KEY(project,run))`); err != nil {
		return err
	}
	if restored {
		if _, err := ex.ExecContext(ctx, `INSERT INTO backup_restore_barriers(project,run,restored_at)
		SELECT s.project_id, s.run_id, ? FROM client_sessions s
		JOIN domain_objects r ON r.kind='Run' AND r.project=s.project_id AND r.id=s.run_id
		WHERE s.sealed_at IS NULL AND s.run_id IS NOT NULL
		AND json_extract(r.body,'$.status') IN ('QUEUED','STARTING','RUNNING','CANCEL_REQUESTED','RECONCILING','LOST')
		ON CONFLICT(project,run) DO UPDATE SET restored_at=excluded.restored_at`, Now()); err != nil {
			return err
		}
	}
	if _, err := ex.ExecContext(ctx, `CREATE TRIGGER IF NOT EXISTS client_session_epoch_no_regression BEFORE UPDATE OF writer_epoch ON client_sessions
		WHEN NEW.writer_epoch < OLD.writer_epoch BEGIN SELECT RAISE(ABORT,'SESSION_EPOCH_REGRESSION'); END;`); err != nil {
		return err
	}
	_, err := ex.ExecContext(ctx, `CREATE TRIGGER IF NOT EXISTS client_session_require_fresh BEFORE UPDATE OF writer_epoch ON client_sessions
		WHEN NEW.writer_epoch > OLD.writer_epoch
		AND NEW.run_id IS NOT NULL
		AND EXISTS(SELECT 1 FROM backup_restore_barriers b WHERE b.project=NEW.project_id AND b.run=NEW.run_id)
		AND EXISTS(SELECT 1 FROM domain_objects r WHERE r.kind='Run' AND r.project=NEW.project_id AND r.id=NEW.run_id
			AND json_extract(r.body,'$.status') IN ('QUEUED','STARTING','RUNNING','CANCEL_REQUESTED','RECONCILING','LOST'))
		AND NOT EXISTS(SELECT 1 FROM runtime_observations o
			WHERE o.project=NEW.project_id AND o.run=NEW.run_id
			AND o.observed_at > (SELECT max(b.restored_at) FROM backup_restore_barriers b WHERE b.project=NEW.project_id AND b.run=NEW.run_id)
			AND json_extract(o.body,'$.children_stopped')=1 AND json_extract(o.body,'$.queue_empty')=1)
		BEGIN SELECT RAISE(ABORT,'RESTORE_FRESH_RECONCILIATION_REQUIRED'); END;`)
	return err
}

package domain

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"researchos.local/research-os/adapters/retrieval"
)

// Reconstruct registered file roots from sealed snapshots. No restored query
// is allowed to fall back to the original machine's absolute source path.
func (s *Service) backupRelocateSources(stage, destination string) error {
	rows, e := s.DB.Query("SELECT project,id FROM retrieval_roots")
	if e != nil {
		return e
	}
	type root struct{ project, id string }
	roots := []root{}
	for rows.Next() {
		var x root
		if e = rows.Scan(&x.project, &x.id); e != nil {
			rows.Close()
			return e
		}
		roots = append(roots, x)
	}
	e = rows.Err()
	rows.Close()
	if e != nil {
		return e
	}
	for _, r := range roots {
		relative := filepath.Join("sources", strings.TrimPrefix(Hash([]any{r.project, r.id}), "sha256:"))
		path := filepath.Join(stage, relative)
		if e = os.MkdirAll(path, 0700); e != nil {
			return e
		}
		rows, e = s.DB.Query("SELECT x.relative_path,u.bytes,x.content_hash FROM retrieval_snapshots x JOIN domain_objects a ON a.project=x.project AND a.kind='Artifact' AND a.id=x.artifact_id JOIN uploaded_content u ON u.project=a.project AND u.storage_key=json_extract(a.body,'$.storage_key') AND u.sealed=1 WHERE x.project=? AND x.root_id=? AND x.status='CURRENT'", r.project, r.id)
		if e != nil {
			return e
		}
		written := map[string]backupSourceFile{}
		for rows.Next() {
			var name, hash string
			var raw []byte
			if e = rows.Scan(&name, &raw, &hash); e != nil {
				rows.Close()
				return e
			}
			name = filepath.FromSlash(name)
			if !filepath.IsLocal(name) || strings.Contains(name, ":") || Digest(raw) != hash {
				rows.Close()
				return fmt.Errorf("RESTORE_SOURCE_INVALID")
			}
			target := filepath.Join(path, name)
			if e = os.MkdirAll(filepath.Dir(target), 0700); e != nil {
				rows.Close()
				return e
			}
			if e = backupWriteSource(target, raw, hash, written); e != nil {
				rows.Close()
				return e
			}
		}
		e = rows.Err()
		rows.Close()
		if e != nil {
			return e
		}
		identity, e := retrieval.Identity(path)
		if e != nil {
			return e
		}
		target, e := filepath.Abs(filepath.Join(stage, relative))
		if e != nil {
			return e
		}
		if _, e = s.DB.Exec("UPDATE retrieval_roots SET path=?,root_identity=? WHERE project=? AND id=?", target, identity, r.project, r.id); e != nil {
			return e
		}
	}
	return nil
}

type backupSourceFile struct {
	info os.FileInfo
	hash string
}

// Snapshot origin paths remain unchanged. Two paths may name the same native
// file (including Windows case aliases), but may only share identical content.
// An existing file is reusable only if this restore created that exact file.
func backupWriteSource(target string, raw []byte, hash string, written map[string]backupSourceFile) error {
	file, err := os.OpenFile(target, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err == nil {
		if _, err = file.Write(raw); err == nil {
			err = file.Sync()
		}
		// File.Stat freezes the identity from this open handle. On Windows,
		// Lstat may defer loading the file ID until SameFile reopens its path.
		info, statErr := file.Stat()
		closeErr := file.Close()
		if err != nil {
			return err
		}
		if statErr != nil {
			return statErr
		}
		if closeErr != nil {
			return closeErr
		}
		written[target] = backupSourceFile{info: info, hash: hash}
		return nil
	}
	if !os.IsExist(err) {
		return err
	}
	info, err := os.Lstat(target)
	if err != nil || !info.Mode().IsRegular() {
		return fmt.Errorf("RESTORE_SOURCE_CONFLICT")
	}
	file, err = os.Open(target)
	if err != nil {
		return fmt.Errorf("RESTORE_SOURCE_CONFLICT")
	}
	defer file.Close()
	info, err = file.Stat()
	if err != nil || !info.Mode().IsRegular() {
		return fmt.Errorf("RESTORE_SOURCE_CONFLICT")
	}
	for _, prior := range written {
		if os.SameFile(prior.info, info) {
			if prior.hash != hash {
				return fmt.Errorf("RESTORE_SOURCE_CONFLICT")
			}
			// Identity and bytes must come from the same handle, even if the
			// pathname is replaced after it is opened.
			actual, err := io.ReadAll(io.LimitReader(file, int64(len(raw))+1))
			if err != nil || Digest(actual) != hash || !bytes.Equal(actual, raw) {
				return fmt.Errorf("RESTORE_SOURCE_CONFLICT")
			}
			return nil
		}
	}
	return fmt.Errorf("RESTORE_SOURCE_CONFLICT")
}

func (s *Service) backupPublishSourcePaths(stage, destination string) error {
	rows, e := s.DB.Query("SELECT project,id,path FROM retrieval_roots")
	if e != nil {
		return e
	}
	type entry struct{ project, id, path string }
	entries := []entry{}
	for rows.Next() {
		var x entry
		if e = rows.Scan(&x.project, &x.id, &x.path); e != nil {
			rows.Close()
			return e
		}
		entries = append(entries, x)
	}
	e = rows.Err()
	rows.Close()
	if e != nil {
		return e
	}
	for _, x := range entries {
		rel, e := filepath.Rel(stage, x.path)
		if e != nil || !filepath.IsLocal(rel) {
			return fmt.Errorf("RESTORE_SOURCE_NOT_ISOLATED")
		}
		abs, e := filepath.Abs(filepath.Join(destination, rel))
		if e != nil {
			return e
		}
		if _, e = s.DB.Exec("UPDATE retrieval_roots SET path=? WHERE project=? AND id=?", abs, x.project, x.id); e != nil {
			return e
		}
	}
	return nil
}

func (s *Service) backupRecomputeAcceptance() (Object, error) {
	tasks, e := backupObjects(s.DB, "SELECT body FROM domain_objects WHERE kind='Task' AND json_extract(body,'$.status')='ACCEPTED'")
	if e != nil {
		return nil, e
	}
	tx, e := s.DB.Begin()
	if e != nil {
		return nil, e
	}
	defer tx.Rollback()
	results := Empty()
	for _, task := range tasks {
		if e = s.acceptedTaskBinding(tx, Str(task, "project_id"), task); e != nil {
			return nil, fmt.Errorf("RESTORE_ACCEPTANCE_INEFFECTIVE: %w", e)
		}
		receipt, e := load(tx, Str(task, "project_id"), "AcceptanceReceipt", Str(task, "acceptance_id"))
		if e != nil {
			return nil, e
		}
		results = append(results, Object{"project_id": task["project_id"], "task_id": task["id"], "acceptance_id": receipt["id"], "receipt_hash": receipt["receipt_hash"], "effective": true})
	}
	return Object{"accepted_tasks_recomputed": results}, nil
}

// Restore is a time reversal: even PREPARED effects might have been sent after
// the snapshot. Fence ALL unfinished effects, invalidate credentials, and force
// trusted runtime reconciliation before the existing W12 resume protocol.
func (s *Service) backupFence(ctx context.Context) (Object, error) {
	runs, e := backupObjects(s.DB, "SELECT body FROM domain_objects WHERE kind='Run' AND json_extract(body,'$.status') IN ('QUEUED','STARTING','RUNNING','CANCEL_REQUESTED','RECONCILING','LOST')")
	if e != nil {
		return nil, e
	}
	effects, e := backupObjects(s.DB, `SELECT body FROM resource_effects x WHERE sequence=(SELECT max(y.sequence) FROM resource_effects y WHERE y.project=x.project AND y.run=x.run AND y.effect_key=x.effect_key) AND json_extract(body,'$.state') IN ('PREPARED','STARTED','UNKNOWN')`)
	if e != nil {
		return nil, e
	}
	tx, e := s.DB.BeginTx(ctx, nil)
	if e != nil {
		return nil, e
	}
	defer tx.Rollback()
	// Restore-local guard survives restart and applies to every existing resume
	// route. A snapshot's old observation is never fresh reconciliation evidence.
	if _, e = tx.Exec(`CREATE TABLE IF NOT EXISTS backup_restore_barriers(project TEXT NOT NULL,run TEXT NOT NULL,restored_at TEXT NOT NULL,PRIMARY KEY(project,run));
CREATE TRIGGER IF NOT EXISTS backup_require_fresh_observation BEFORE UPDATE ON domain_objects
WHEN NEW.kind='Run' AND json_extract(NEW.body,'$.lease_epoch')>json_extract(OLD.body,'$.lease_epoch')
AND EXISTS(SELECT 1 FROM backup_restore_barriers b WHERE b.project=NEW.project AND b.run=NEW.id)
AND NOT EXISTS(SELECT 1 FROM runtime_observations o JOIN backup_restore_barriers b ON b.project=o.project AND b.run=o.run WHERE o.project=NEW.project AND o.run=NEW.id AND o.epoch=json_extract(OLD.body,'$.lease_epoch') AND o.observed_at>b.restored_at AND json_extract(o.body,'$.children_stopped')=1 AND json_extract(o.body,'$.queue_empty')=1)
BEGIN SELECT RAISE(ABORT,'RESTORE_FRESH_RECONCILIATION_REQUIRED'); END;`); e != nil {
		return nil, e
	}
	if e = EnsureClientSessionFence(ctx, tx); e != nil {
		return nil, e
	}
	if e = fenceRestoredClientQueues(tx); e != nil {
		return nil, e
	}
	if _, e = tx.Exec("UPDATE auth_credentials SET revoked=1"); e != nil {
		return nil, e
	}
	for _, r := range runs {
		if _, e = tx.Exec("INSERT INTO backup_restore_barriers(project,run,restored_at) VALUES(?,?,?) ON CONFLICT(project,run) DO UPDATE SET restored_at=excluded.restored_at", r["project_id"], r["id"], Now()); e != nil {
			return nil, e
		}
		status := "RECONCILING"
		if r["status"] == "CANCEL_REQUESTED" {
			status = "CANCEL_REQUESTED"
		}
		Merge(r, Object{"status": status, "lease_token_hash": Digest([]byte(ID() + ID())), "lease_expires_at": "1970-01-01T00:00:00Z"})
		if e = bump(r); e != nil {
			return nil, e
		}
		if e = s.put(tx, "Run", r); e != nil {
			return nil, e
		}
		if e = s.event(tx, Str(r, "project_id"), "Run", r, "restore-local-admin", ID(), "RUN_CHANGED"); e != nil {
			return nil, e
		}
	}
	for _, o := range effects {
		o["state"] = "UNKNOWN"
		o["restore_reason"] = "SNAPSHOT_MAY_PREDATE_EXTERNAL_DISPATCH"
		if e = effectAppend(tx, Str(o, "project_id"), Str(o, "run_id"), Str(o, "key"), o); e != nil {
			return nil, e
		}
	}
	if e = tx.Commit(); e != nil {
		return nil, e
	}
	return Object{"active_runs_fenced": len(runs), "effects_requiring_reconciliation": len(effects), "credentials": "REVOKED_REPROVISION_LOCALLY", "external_keys": "NOT_INCLUDED_RESTORE_SEPARATELY", "external_actions_dispatched": 0, "outbox_policy": "preserved; internal consumers deduplicate by event ID; external delivery requires provider reconciliation", "expected_differences": []any{"revoked session credentials", "relocated source roots", "active runs RECONCILING with expired leases and new revisions", "unfinished effects UNKNOWN", "restore audit events"}}, nil
}

package domain

import (
	"context"
	"database/sql"
	"strings"
	"time"
)

var runtimeOperations = map[string]bool{}

func init() {
	for _, id := range strings.Fields("registerRuntime getRuntimeRegistration listRuntimeRegistration qualifyRuntime getRun listRun heartbeatRun reportRun cancelRun acknowledgeRunCancellation reconcileRun") {
		runtimeOperations[id] = true
		implemented[id] = true
	}
}

// BeginRuntimeQualification consumes a host-approved private plan in one transaction.
func (s *Service) BeginRuntimeQualification(ctx context.Context, token, project, taskID, runtimeID, executor string) (Object, string, error) {
	tx, e := s.DB.BeginTx(ctx, nil)
	if e != nil {
		return nil, "", e
	}
	defer tx.Rollback()
	p, e := authenticate(tx, token)
	if e != nil {
		return nil, "", e
	}
	if !p.HasRole("OWNER") || !p.Allowed(project, "", "", false) {
		return nil, "", Fail(403, "FORBIDDEN", "qualification requires local owner")
	}
	r, lease, e := s.beginRuntimeQualification(tx, p, project, taskID, runtimeID, executor)
	if e != nil {
		return nil, "", e
	}
	return r, lease, tx.Commit()
}

// createRuntimeRun shares the Run identity, epoch and ownership transaction with normal claims.
func (s *Service) createRuntimeRun(tx *sql.Tx, project string, task Object, runtimeID, executor string) (Object, string, error) {
	taskID := Str(task, "id")
	var e error
	var epoch int64
	if e = tx.QueryRow("SELECT coalesce(max(CAST(json_extract(body,'$.lease_epoch') AS INTEGER)),0)+1 FROM domain_objects WHERE project=? AND kind='Run' AND json_extract(body,'$.task_id')=?", project, taskID).Scan(&epoch); e != nil {
		return nil, "", e
	}
	lease := ID() + ID()
	r := Merge(Base(project), Object{"task_id": taskID, "runtime_id": runtimeID, "executor_principal_id": executor, "attempt": epoch, "status": "QUEUED", "input_refs": task["input_refs"], "context_bundle_id": task["context_bundle_id"], "external_run_id": nil, "workspace_snapshot_id": ID(), "lease_token_hash": Digest([]byte(lease)), "lease_expires_at": time.Now().UTC().Add(90 * time.Second).Format(time.RFC3339Nano), "heartbeat_at": nil, "checkpoint_artifact_id": nil, "result_artifact_ids": Empty(), "execution_report": nil, "exit_code": nil, "runtime_settled_at": nil, "cancel_requested_at": nil, "cancel_confirmed_at": nil, "children_stopped": nil, "queue_empty": nil, "started_at": nil, "ended_at": nil, "lease_epoch": epoch})
	if e = s.put(tx, "Run", r); e != nil {
		return nil, "", e
	}
	if _, e = tx.Exec("INSERT INTO auth_grants(principal,project,task,run) VALUES(?,?,?,?)", executor, project, taskID, r["id"]); e != nil {
		return nil, "", e
	}
	if e = bump(task); e != nil {
		return nil, "", e
	}
	task["active_run_id"] = r["id"]
	task["assigned_principal_id"] = executor
	if e = s.put(tx, "Task", task); e != nil {
		return nil, "", e
	}
	return r, lease, nil
}

// ObserveRuntime is only called by the trusted worker bridge. There is no HTTP write endpoint.
// An old epoch observation is retained for reconciliation but cannot change current Run state.
func (s *Service) ObserveRuntime(ctx context.Context, project, runID string, epoch int64, observation Object) error {
	return s.observeRuntime(ctx, project, runID, epoch, observation, false)
}
func (s *Service) observeRuntime(ctx context.Context, project, runID string, epoch int64, observation Object, coordinator bool) error {
	if epoch < 1 {
		return Fail(400, "INVALID_REQUEST", "invalid epoch")
	}
	spec, _ := observation["spec"].(map[string]any)
	n, e := Num(spec, "epoch")
	if e != nil || n != epoch || spec["run_id"] != runID {
		return Fail(422, "GATE_FAILED", "observation identity mismatch")
	}
	tx, e := s.DB.BeginTx(ctx, nil)
	if e != nil {
		return e
	}
	defer tx.Rollback()
	r, e := load(tx, project, "Run", runID)
	if e != nil {
		return e
	}
	if spec["task_id"] != r["task_id"] {
		return Fail(422, "GATE_FAILED", "observation task mismatch")
	}
	dispatch, de := runtimeDispatch(tx, project, runID, epoch)
	if de != nil && de != sql.ErrNoRows {
		return de
	}
	if de == nil {
		if !coordinator {
			return Fail(403, "FORBIDDEN", "native dispatch observation requires bound coordinator")
		}
		sequence, se := Num(observation, "observation_sequence")
		prior, _ := Num(dispatch, "observation_sequence")
		if se != nil || sequence < 1 || observation["dispatch_key"] != dispatch["dispatch_key"] || observation["manifest_hash"] != dispatch["manifest_hash"] || observation["worker"] != dispatch["worker"] || Hash(observation["identity"]) != Hash(dispatch["identity"]) || len(dispatch["identity"].(map[string]any)) == 0 || sequence < prior || (sequence == prior && Hash(observation) != dispatch["observation_hash"]) {
			return Fail(422, "GATE_FAILED", "observation differs from durable native dispatch identity")
		}
		if observation["children_stopped"] != true || observation["streams_drained"] != true || observation["cleanup_complete"] != true || Str(observation, "ended") == "" {
			return Fail(422, "GATE_FAILED", "observation is not a drained terminal fact")
		}
		if _, e = tx.Exec("UPDATE runtime_dispatches SET state='OBSERVED',observation_sequence=?,observation_hash=?,updated_at=? WHERE project=? AND run=? AND epoch=?", sequence, Hash(observation), Now(), project, runID, epoch); e != nil {
			return e
		}
	}
	_, e = tx.Exec("INSERT OR IGNORE INTO runtime_observations(project,run,epoch,receipt_hash,body,observed_at) VALUES(?,?,?,?,?,?)", project, runID, epoch, Hash(observation), string(Bytes(observation)), Now())
	if e != nil {
		return e
	}
	return tx.Commit()
}
func runtimeObservation(tx *sql.Tx, project string, r Object) (Object, error) {
	var raw string
	e := tx.QueryRow("SELECT body FROM runtime_observations WHERE project=? AND run=? AND epoch=? ORDER BY observed_at DESC LIMIT 1", project, r["id"], r["lease_epoch"]).Scan(&raw)
	if e != nil {
		return nil, Fail(422, "GATE_FAILED", "trusted runtime observation required")
	}
	return Decode([]byte(raw))
}
func currentRun(tx *sql.Tx, p Principal, project, id string) (Object, error) {
	r, e := load(tx, project, "Run", id)
	if e != nil {
		return nil, e
	}
	if !p.Allowed(project, Str(r, "task_id"), id, false) {
		return nil, Fail(404, "NOT_FOUND", "run unavailable")
	}
	return r, nil
}
func runTerminal(r Object) bool {
	return r["status"] == "SETTLED" || r["status"] == "FAILED" || r["status"] == "CANCELLED"
}
func runtimeLease(tx *sql.Tx, p Principal, project string, r, b Object) error {
	epoch, e := Num(b, "lease_epoch")
	current, _ := Num(r, "lease_epoch")
	expires, te := time.Parse(time.RFC3339Nano, Str(r, "lease_expires_at"))
	if p.ID != r["executor_principal_id"] || e != nil || epoch != current || Digest([]byte(Str(b, "lease_token"))) != r["lease_token_hash"] || te != nil || !time.Now().Before(expires) {
		return Fail(409, "LEASE_EXPIRED", "run lease no longer current")
	}
	task, e := load(tx, project, "Task", Str(r, "task_id"))
	if e != nil || task["active_run_id"] != r["id"] {
		return Fail(409, "LEASE_EXPIRED", "run no longer owns task")
	}
	return nil
}
func (s *Service) runtimeOperation(tx *sql.Tx, p Principal, project, id string, b Object, op, cid string) (Object, string, int, error) {
	return s.runtimeOperationMode(tx, p, project, id, b, op, cid, false)
}

// recoveryFacts is only set by local journal ingestion after exact epoch and
// native proof checks. It never bypasses a lease for execution or heartbeat.
func (s *Service) runtimeOperationMode(tx *sql.Tx, p Principal, project, id string, b Object, op, cid string, recoveryFacts bool) (Object, string, int, error) {
	if recoveryFacts && op != "reportRun" && op != "acknowledgeRunCancellation" {
		return nil, "", 0, Fail(403, "FORBIDDEN", "recovery can import terminal facts only")
	}
	if op == "registerRuntime" {
		r := Merge(Base(project), b)
		Merge(r, Object{"status": "REGISTERED", "qualification_ids": Empty(), "health_checked_at": nil, "supports_resume": false, "resume_evidence_ref": nil})
		return r, "RuntimeRegistration", 201, s.put(tx, "RuntimeRegistration", r)
	}
	if op == "qualifyRuntime" {
		r, e := s.qualifyRuntime(tx, p, project, id, b)
		return r, "RuntimeRegistration", 200, e
	}
	r, e := currentRun(tx, p, project, id)
	if e != nil {
		return nil, "", 0, e
